// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount1 > 0 && amount2 > 0);
        amount1 = bound(amount1, 1, 10 ether);
        amount2 = bound(amount2, 1, 10 ether);

        vm.deal(actor, amount1 + amount2);
        vm.prank(actor);
        c.Put{value: amount1}(0);
        vm.prank(actor);
        c.Put{value: amount2}(0);

        (, uint256 bal) = c.Acc(actor);
        assertEq(bal, amount1 + amount2, "balance must accumulate deposits");
    }
}
